 "matiere": { "key": "sante", "fr": "Santé", "nl": "Gezondheid", "en": "Health" },
 "titre":           { "fr": "Vingt millions d'euros de déficit en plus pour les hôpitaux publics de Brême, sans explication claire", "nl": "Twintig miljoen euro extra tekort voor de openbare ziekenhuizen van Bremen, zonder duidelijke uitleg", "en": "Twenty million euros of extra deficit for Bremen's public hospitals, with no clear explanation" },
