 "matiere": { "key": "fiscalite", "fr": "Fiscalité et finances publiques", "nl": "Fiscaliteit en openbare financiën", "en": "Taxation and public finances" },
 "titre":           { "fr": "Pour tenir son budget, Brême allonge d'une heure la semaine de travail de ses fonctionnaires sans compensation", "nl": "Om zijn begroting te halen verlengt Bremen de werkweek van zijn ambtenaren met een uur zonder compensatie", "en": "To balance its budget, Bremen extends its civil servants' working week by one hour without compensation" },
